*{box-sizing:border-box} :root{--ink:#383235;--muted:#8d8180;--rose:#c47984;--rose-dark:#a95c69;--paper:#f7f2ec;--line:#eee5df;--plum:#654753;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',sans-serif}html,body{margin:0;min-height:100%;font-family:var(--sans);color:var(--ink)}body{background:var(--paper);background-image:radial-gradient(ellipse at 50% -30%,#fff 0%,transparent 55%);padding:0 34px}.game-shell{max-width:1390px;margin:0 auto;min-height:100vh;display:flex;flex-direction:column}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e8ded8}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink)}.brand-mark{width:37px;height:37px;border:1px solid #d5afb0;border-radius:50%;display:grid;place-items:center;font-family:var(--serif);font-size:22px;color:var(--rose-dark);position:relative}.brand-mark span{font-size:12px;position:absolute;right:2px;bottom:2px;background:var(--paper)}.brand-name{font-weight:700;font-size:12px;letter-spacing:1.55px;line-height:1.3}.brand-name i{font-family:var(--serif);font-weight:500;color:var(--rose);font-size:16px}.brand-name small{display:block;color:#a89c97;font-weight:600;letter-spacing:1.65px;font-size:8px;margin-top:3px}.chapter-pill{font-size:10px;font-weight:700;letter-spacing:1.2px;color:#877975;background:#eee7e2;border-radius:20px;padding:10px 15px}.chapter-pill b{color:#c3a9a0;margin:0 4px}.chapter-dot,.live-dot{display:inline-block;width:6px;height:6px;background:#d39791;border-radius:50%;vertical-align:1px;margin-right:6px}.sound-button{border:1px solid #e7ddd7;background:transparent;border-radius:22px;padding:9px 13px;color:#8e7775;font:600 10px var(--sans);cursor:pointer}.sound-button span{margin-left:5px}.game-grid{display:grid;grid-template-columns:minmax(210px,.88fr) minmax(340px,1.22fr) minmax(320px,1fr);gap:30px;flex:1;padding:29px 0 25px;min-height:680px}.story-column{display:flex;flex-direction:column;gap:17px}.story-card{background:#fffdfa;border:1px solid #eee6e0;border-radius:3px;padding:25px 24px 20px;box-shadow:0 8px 26px #6c4a3510;position:relative;overflow:hidden}.story-card:after{content:'✿';font-family:var(--serif);font-size:114px;position:absolute;right:-21px;top:-37px;color:#f8f0ed;transform:rotate(-20deg);pointer-events:none}.story-topline{display:flex;justify-content:space-between;align-items:center;position:relative;z-index:1}.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.55px;color:#b07a79}.story-number{font-size:9px;letter-spacing:1px;color:#c4b8b0;font-weight:700}.story-card h1{font:600 clamp(28px,2.25vw,37px)/1.16 var(--serif);letter-spacing:-.7px;margin:24px 0 16px;position:relative;z-index:1;color:#413537}.story-card h1 em,.wardrobe-heading h2 em{font-weight:500;color:var(--rose)}.story-copy{font-size:12px;line-height:1.8;color:#817775;margin:0 0 20px}.story-note{border-left:2px solid #d7a2a3;padding:9px 11px;background:#fbf6f3;display:flex;gap:10px;font-size:10px;line-height:1.6;color:#827775}.story-note b{font-size:9px;letter-spacing:.7px;text-transform:uppercase;color:#b07979}.note-icon{color:#ce9897;font-size:15px}.story-progress{border-top:1px solid #f0e9e4;margin-top:21px;padding-top:15px;display:flex;align-items:center;gap:9px;font-size:8px;letter-spacing:.8px;color:#a79a94;font-weight:700}.progress-track{height:3px;background:#f0e9e4;flex:1;border-radius:3px;overflow:hidden}.progress-track i{height:100%;display:block;background:var(--rose);width:0;transition:width .35s}.story-progress>b{color:#897a76;white-space:nowrap}.goal-card{display:flex;gap:13px;align-items:flex-start;padding:16px;background:#f1e8e4;border-radius:3px}.goal-icon{font-size:19px;color:#c38789}.goal-card strong{font:600 14px var(--serif);color:#59474a}.goal-card p{font-size:10px;line-height:1.7;color:#837673;margin:5px 0 0}.goal-card p b{color:#a76d73}.journal-link{border-top:1px solid #eae0da;border-bottom:1px solid #eae0da;padding:13px 3px;display:flex;align-items:center;gap:11px;color:#807270}.journal-icon{height:31px;width:31px;border:1px solid #e5d6cf;border-radius:50%;display:grid;place-items:center;color:#bd8789;font-size:14px}.journal-link b{display:block;font:600 13px var(--serif);color:#57494a}.journal-link small{display:block;font-size:9px;color:#a49590;margin-top:3px}.journal-arrow{margin-left:auto;color:#c29391;font-size:15px}.dressing-room{background:#f0e5df;position:relative;min-height:630px;border:1px solid #eadbd4;overflow:hidden;display:flex;flex-direction:column}.room-top{height:45px;padding:0 17px;display:flex;align-items:center;justify-content:space-between;z-index:2}.room-label{font-size:9px;font-weight:700;letter-spacing:1.2px;color:#927c77}.live-dot{background:#a9aa88;width:6px;height:6px}.reset-button{background:#ffffff80;border:1px solid #e6d9d2;color:#957f7a;padding:6px 9px;border-radius:2px;font:600 9px var(--sans);cursor:pointer}.scene-tag{position:absolute;top:68px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px;font-weight:700;letter-spacing:1.7px;color:#ad9290;z-index:2}.scene-tag span{color:#d39c9a;margin:0 6px}.model-stage{position:relative;flex:1;min-height:500px;overflow:hidden;background:linear-gradient(180deg,#eadbd9 0%,#f2e7e1 60%,#c9b3aa 60.2%,#d1bdb4 100%)}.model-stage:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent 0 10%,#ffffff18 10.1% 10.3%,transparent 10.4% 88%,#ffffff1c 88.1% 88.3%,transparent 88.4%),radial-gradient(ellipse at 50% 30%,#fff8 0%,transparent 58%)}.spotlight{position:absolute;width:390px;height:480px;top:55px;left:50%;transform:translateX(-50%);background:linear-gradient(180deg,#fff8 0%,#ffffff05 68%,transparent);clip-path:polygon(40% 0,60% 0,100% 100%,0 100%);opacity:.7}.cityline{position:absolute;left:0;right:0;bottom:40%;height:100px;opacity:.38;display:flex;align-items:flex-end;justify-content:space-around}.cityline i{width:7%;height:38px;background:#ae9495;border-radius:2px 2px 0 0;position:relative}.cityline i:nth-child(2n){height:59px;width:5%}.cityline i:nth-child(3n){height:76px;width:9%;background:#c1a6a4}.cityline i:after{content:'▪ ▪';position:absolute;top:10px;left:22%;font-size:8px;line-height:13px;letter-spacing:5px;color:#f4dfcd}.model-shadow{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);height:17px;width:150px;border-radius:50%;background:#7359504a;filter:blur(6px)}.doll{position:absolute;z-index:1;height:min(75%,470px);width:auto;max-width:80%;bottom:21px;left:50%;transform:translateX(-50%);filter:drop-shadow(0 8px 8px #553c3512);overflow:visible}.model-caption{position:absolute;bottom:17px;left:18px;font:italic 11px var(--serif);color:#826f6b;z-index:2}.caption-star{color:#bc8584;margin-left:5px}.sparkle{position:absolute;color:#fff4ea;z-index:1;text-shadow:0 1px 5px #fff;font-size:22px}.sparkle-one{top:26%;left:18%}.sparkle-two{right:18%;top:41%;font-size:16px}.sparkle-three{top:18%;right:29%;font-size:28px}.look-summary{height:41px;background:#f8f3ef;display:flex;align-items:center;justify-content:center;gap:8px;font-size:10px;color:#9e8d87;letter-spacing:.2px}.summary-sparkle{font-size:15px;color:#c88e8e}.wardrobe-column{background:#fffdfa;border:1px solid #eee6df;display:flex;flex-direction:column;padding:22px 22px 15px;box-shadow:0 8px 26px #6c4a3508}.wardrobe-heading{display:flex;align-items:flex-end;justify-content:space-between}.wardrobe-heading h2{font:600 26px var(--serif);margin:7px 0 16px;letter-spacing:-.5px}.piece-count{font:600 11px var(--sans);color:#ba8683;margin-bottom:21px}.category-tabs{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid #eee5df}.category-tab{border:0;background:transparent;padding:10px 2px 11px;color:#a09691;font:600 10px var(--sans);cursor:pointer;position:relative;white-space:nowrap}.category-tab span{font-size:8px;color:#c4b7b1;margin-left:3px}.category-tab.active{color:#a8606d}.category-tab.active:after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:2px;background:#c47d86}.category-tab:focus-visible,.item-card:focus-visible,button:focus-visible{outline:2px solid #c57d86;outline-offset:2px}.wardrobe-content{flex:1;min-height:250px}.options-heading{display:flex;justify-content:space-between;margin:17px 0 12px;font-size:8px;letter-spacing:1px;color:#9e8b86;font-weight:700}.options-heading span+span{font-size:7px;color:#c0aaa3}.item-list{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.item-card{padding:0;border:1px solid #efe7e2;background:#fbf8f5;text-align:left;cursor:pointer;position:relative;transition:.18s;border-radius:2px;overflow:hidden;color:inherit}.item-card:hover{border-color:#d6a5a4;transform:translateY(-2px);box-shadow:0 5px 12px #925c5a15}.item-card.selected{border:1.5px solid #ba777c;background:#fff9f6;box-shadow:0 3px 10px #925c5a14}.item-visual{height:79px;display:grid;place-items:center;background:linear-gradient(145deg,#f6efeb,#f0e7e1);font-size:35px;position:relative;overflow:hidden}.item-visual:after{content:'';position:absolute;width:66px;height:66px;border-radius:50%;background:#fff7;filter:blur(13px)}.item-visual span{position:relative;z-index:1;filter:drop-shadow(0 3px 2px #4f2f311b)}.item-info{padding:7px 7px 8px;min-height:47px}.item-name{font:600 10px var(--serif);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.item-meta{display:flex;align-items:center;justify-content:space-between;margin-top:5px;font-size:7px;color:#9d8e89;letter-spacing:.4px}.item-swatch{height:8px;width:8px;border-radius:50%;display:inline-block;margin-right:3px;vertical-align:-1px;border:1px solid #00000012}.item-check{position:absolute;top:5px;right:5px;width:16px;height:16px;border-radius:50%;background:#ba777c;color:#fff;display:none;place-items:center;font-size:10px;z-index:2}.item-card.selected .item-check{display:grid}.stylist-tip{display:flex;gap:9px;align-items:center;border-top:1px solid #f0e9e4;margin-top:13px;padding:10px 0 0;color:#9b8a84}.tip-icon{font-size:17px;color:#c9908e}.stylist-tip p{font-size:9px;line-height:1.5;margin:0}.stylist-tip b{font:600 11px var(--serif);color:#816d6b}.reveal-button{height:43px;background:#b96f7a;color:white;border:0;border-radius:2px;display:flex;align-items:center;justify-content:center;gap:15px;font:700 9px var(--sans);letter-spacing:1.5px;cursor:pointer;transition:.2s}.reveal-button:not(:disabled):hover{background:#9e5966;box-shadow:0 6px 16px #a95c6940;transform:translateY(-1px)}.reveal-button:disabled{background:#ddc3c0;color:#fff9;cursor:not-allowed}.button-arrow{font-size:16px;font-weight:400}.reveal-hint{text-align:center;color:#aa9a94;font-size:8px;letter-spacing:.4px;margin:8px 0 0;min-height:10px}.footer{height:42px;border-top:1px solid #e8ded8;display:flex;align-items:center;gap:8px;font-size:8px;letter-spacing:1.4px;color:#aa9b95;font-weight:700}.footer>span{font-size:13px;color:#c68d8a}.footer-right{margin-left:auto}.footer-right b{color:#d09391;margin-left:4px}.modal-backdrop{position:fixed;inset:0;background:#352b30a8;backdrop-filter:blur(5px);z-index:10;display:none;align-items:center;justify-content:center;padding:18px}.modal-backdrop.open{display:flex;animation:fade .25s}.ending-card{position:relative;background:#fffaf6;width:min(470px,100%);padding:35px 40px 30px;text-align:center;border:1px solid #fff;box-shadow:0 22px 65px #24181c55;animation:rise .35s;max-height:92vh;overflow:auto}.modal-close{position:absolute;top:11px;right:14px;background:none;border:0;font-size:24px;color:#aa9691;cursor:pointer}.ending-confetti{color:#c58d8d;font-size:16px;letter-spacing:5px}.ending-kicker{font-size:8px;letter-spacing:2px;font-weight:700;color:#b37c7d;margin-top:11px}.ending-card h2{font:600 34px var(--serif);margin:10px 0 11px;color:#433539}.ending-copy{font-size:12px;line-height:1.8;color:#857674;margin:0 auto;max-width:350px}.score-display{display:flex;align-items:center;justify-content:center;gap:12px;margin:20px 0;color:#c18c83}.score-display span:first-child{font-size:8px;font-weight:700;letter-spacing:1.5px;color:#a38b84}.score-display strong{font:600 27px var(--serif);color:#624a50}.ending-choice{padding:14px;background:#f7efea;text-align:left}.ending-choice p{font:500 14px/1.5 var(--serif);margin:8px 0 11px;color:#55474a}.choice-buttons{display:flex;gap:8px}.choice-buttons button,.secondary-button{flex:1;border:1px solid #d7b5af;background:#fffaf6;padding:10px 8px;color:#93686a;font:600 10px var(--sans);cursor:pointer}.choice-buttons button:hover,.secondary-button:hover{background:#f3e5e0}.ending-actions{display:flex;gap:9px;margin-top:13px}.secondary-button{background:#b96f7a;color:#fff;border-color:#b96f7a}.secondary-button:hover{background:#9e5966;color:#fff}.ending-choice .eyebrow{font-size:8px}.ending-choice.answered{opacity:.7}.ending-choice.answered button{pointer-events:none}@keyframes fade{from{opacity:0}to{opacity:1}}@keyframes rise{from{transform:translateY(12px);opacity:0}to{transform:none;opacity:1}}
/* SVG styling, garment pieces are layered by game.js */
.garment{transition:fill .2s,stroke .2s}.pattern{opacity:.28;pointer-events:none}.doll .line-art{fill:none;stroke:#ffffff9a;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.doll .detail-dark{fill:none;stroke:#5f3b4b;stroke-width:2}.doll .detail-light{fill:none;stroke:#fff9;stroke-width:2}.accessory{filter:drop-shadow(0 1px 1px #54363c38)}
@media(min-width:1200px){.game-grid{gap:34px;padding-top:36px}.story-card{padding:28px}.wardrobe-column{padding:24px 24px 17px}.item-visual{height:91px}.item-info{min-height:48px}.dressing-room{min-height:660px}.game-grid{min-height:700px}.model-stage{min-height:535px}}
@media(max-width:980px){body{padding:0 19px}.game-grid{grid-template-columns:minmax(200px,.8fr) minmax(330px,1.2fr);gap:20px}.dressing-room{grid-column:2;grid-row:1;min-height:590px}.story-column{grid-column:1;grid-row:1}.wardrobe-column{grid-column:1/-1;grid-row:2}.item-visual{height:100px}.item-list{grid-template-columns:repeat(6,1fr)}.wardrobe-content{min-height:unset}.story-card h1{font-size:32px}.game-grid{min-height:unset}}
@media(max-width:650px){body{padding:0 12px}.topbar{height:65px}.chapter-pill{font-size:8px;padding:8px 10px}.brand-mark{height:32px;width:32px;font-size:19px}.brand-name{font-size:10px}.sound-button{padding:8px 10px}.sound-button span{display:none}.game-grid{display:flex;flex-direction:column;gap:15px;padding:15px 0 17px}.dressing-room{order:0;min-height:460px;height:58vh;max-height:570px}.story-column{order:1;display:grid;grid-template-columns:1fr 1fr;gap:10px}.story-card{grid-column:1/-1;padding:19px 18px}.story-card h1{font-size:30px;margin:15px 0 10px}.story-copy{font-size:11px;line-height:1.65;margin-bottom:12px}.story-note{padding:7px 9px}.story-progress{margin-top:13px;padding-top:11px}.goal-card{padding:12px;align-items:center}.goal-card p{font-size:9px}.journal-link{padding:10px 3px}.wardrobe-column{order:2;padding:19px 16px 14px}.wardrobe-heading h2{font-size:24px}.item-list{grid-template-columns:repeat(3,1fr)}.item-visual{height:79px}.wardrobe-content{min-height:unset}.stylist-tip{margin-top:10px}.footer{font-size:7px}.model-stage{min-height:0}.doll{height:78%;max-height:420px}.ending-card{padding:32px 22px 22px}.ending-card h2{font-size:29px}}
@media(max-width:380px){.chapter-pill{display:none}.dressing-room{height:420px}.goal-card p{font-size:8px}.category-tab{font-size:9px}.wardrobe-column{padding-left:12px;padding-right:12px}.item-visual{height:72px}}

