const labels={top:'CHOOSE A TOP',bottom:'CHOOSE A BOTTOM',shoes:'PICK YOUR SHOES',accessory:'ADD AN EXTRA'};
const storyBeats=[
 {copy:'Your best friend Jules has one last look to style before the rooftop runway begins. The city is glowing, the playlist is ready—and the final model just texted, “Make it feel like me.”',quote:'“Something dreamy, but with a little main-character energy?”'},
 {copy:'A message from the model pops up: “I found the old photo booth strips from our first show.” Jules laughs. This collection started as a thrift-store dare—and somehow became a runway.',quote:'“We made this together. Let’s make it unforgettable.”'},
 {copy:'The rooftop fills with friends, fairy lights, and a little pre-show flutter. A sudden breeze catches the fabric. The look needs one last detail that says this is your moment.',quote:'“I’m nervous. But the good kind, you know?”'},
 {copy:'The music starts. The model steps into the light, and the whole rooftop leans in. Jules squeezes your hand—whatever happens next, this is a story you made together.',quote:'“Ready when you are, stylist.”'}
];
let selected={top:null,bottom:null,shoes:null,accessory:null};let category='top';let storyStep=0;let soundOn=false;let audioContext=null;let saved=0;let choiceMade=false;
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function renderItems(){const list=$('#itemList');list.innerHTML='';catalog[category].forEach((item,index)=>{const button=document.createElement('button');button.className='item-card'+(selected[category]?.id===item.id?' selected':'');button.type='button';button.setAttribute('aria-pressed',selected[category]?.id===item.id?'true':'false');button.setAttribute('aria-label',`${item.name}, ${item.style.toLowerCase()} style`);button.innerHTML=`<span class="item-check">✓</span><span class="item-visual" style="--swatch:${item.color}"><span>${item.emoji}</span></span><span class="item-info"><span class="item-name">${item.name}</span><span class="item-meta"><span><i class="item-swatch" style="background:${item.color}"></i>${item.style}</span><span>0${index+1}</span></span></span>`;button.addEventListener('click',()=>selectItem(category,item));list.append(button)});$('#categoryTitle').textContent=labels[category];}
function selectItem(cat,item){selected[cat]=item;renderItems();drawLook();updateProgress();playTone(540,.045);if(!selected.bottom&&cat==='top')setTip('Lovely start. A little movement in the skirt or trousers will make it runway-ready.');else if(!selected.accessory)setTip('The story is coming together. What detail will make this look feel unmistakably yours?');else setTip('This look has a point of view. Trust it—and get ready for your reveal!')}
function setTip(text){$('#stylistTip').innerHTML=`<span class="tip-icon">✳</span><p><b>Stylist note</b><br>${text}</p>`}
